'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Uint32Array(b.length + 1);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

function sequences(alphabet, maxLength) {
  const all = [Object.freeze([])];
  let level = all;
  for (let length = 1; length <= maxLength; length++) {
    const next = [];
    for (const prefix of level) {
      for (const line of alphabet) next.push(Object.freeze([...prefix, line]));
    }
    all.push(...next);
    level = next;
  }
  return all;
}

test('exhaustive minimality, deterministic ordering, and patch roundtrips', () => {
  const inputs = sequences(['', 'x', '+x'], 4);
  let pairs = 0;
  for (const a of inputs) {
    for (const b of inputs) {
      const script = diffLines(a, b);
      assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
      assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
      assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
      assert.deepEqual(diffLines(a, b), script);
      let inserted = false;
      for (const { op } of script) {
        if (op === 'equal') inserted = false;
        else if (op === 'insert') inserted = true;
        else {
          assert.equal(op, 'delete');
          assert.equal(inserted, false);
        }
      }
      for (let context = 0; context <= 3; context++) {
        const hunks = unifiedHunks(a, b, { context });
        for (const hunk of hunks) {
          Object.freeze(hunk.lines);
          Object.freeze(hunk);
        }
        Object.freeze(hunks);
        assert.deepEqual(applyHunks(a, hunks), b);
        if (script.every(e => e.op === 'equal')) assert.deepEqual(hunks, []);
      }
      pairs++;
    }
  }
  console.log(`Checked ${pairs} input pairs and ${pairs * 4} roundtrips`);
});

test('zero-length range coordinates and literal prefixes', () => {
  const cases = [
    [[], [''], [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+'] }]],
    [[''], [], [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-'] }]],
    [['a'], ['x', 'a'], [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] }]],
    [['a'], ['a', 'x'], [{ oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+x'] }]],
    [['x', 'a'], ['a'], [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] }]],
    [['a', 'x'], ['a'], [{ oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-x'] }]],
    [['-a'], ['+b'], [{ oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: ['--a', '++b'] }]],
  ];
  for (const [a, b, expected] of cases) {
    assert.deepEqual(unifiedHunks(a, b, { context: 0 }), expected);
    assert.deepEqual(applyHunks(a, expected), b);
  }
  const a = [' a', '-b', '+c', ''];
  const b = [' a', '-b', '+d', ''];
  assert.deepEqual(unifiedHunks(a, b), [{
    oldStart: 1, oldLines: 4, newStart: 1, newLines: 4,
    lines: ['  a', ' -b', '-+c', '++d', ' '],
  }]);
  const copy = applyHunks(a, []);
  assert.deepEqual(copy, a);
  assert.notEqual(copy, a);
});

test('context touching merges, separated context and global offsets', () => {
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd'], ['A', 'b', 'c', 'D'], { context: 1 }), [{
    oldStart: 1, oldLines: 4, newStart: 1, newLines: 4,
    lines: ['-a', '+A', ' b', ' c', '-d', '+D'],
  }]);
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd', 'e'], ['A', 'b', 'c', 'd', 'E'], { context: 1 }), [
    { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: ['-a', '+A', ' b'] },
    { oldStart: 4, oldLines: 2, newStart: 4, newLines: 2, lines: [' d', '-e', '+E'] },
  ]);
  const a = ['a', 'b', 'c', 'd', 'e', 'f'];
  const b = ['top', 'a', 'b', 'c', 'e', 'f', 'tail'];
  const hunks = [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] },
    { oldStart: 4, oldLines: 1, newStart: 4, newLines: 0, lines: ['-d'] },
    { oldStart: 6, oldLines: 0, newStart: 7, newLines: 1, lines: ['+tail'] },
  ];
  assert.deepEqual(unifiedHunks(a, b, { context: 0 }), hunks);
  assert.deepEqual(applyHunks(a, hunks), b);
  assert.deepEqual(applyHunks([], [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+a'] },
    { oldStart: 0, oldLines: 0, newStart: 2, newLines: 1, lines: ['+b'] },
  ]), ['a', 'b']);
});

test('malformed, mismatched, overlapping and misordered patches reject with index', () => {
  const a = Object.freeze(['a', 'b', 'c']);
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const malformed = [null, undefined, 1, {},
    { ...valid, oldStart: -1 }, { ...valid, oldStart: 0 },
    { ...valid, oldStart: 1.5 }, { ...valid, oldStart: 5 },
    { ...valid, oldLines: 4 }, { ...valid, oldLines: -1 },
    { ...valid, oldLines: Infinity }, { ...valid, newStart: 0 },
    { ...valid, newStart: 3 }, { ...valid, newLines: 0 },
    { ...valid, newLines: NaN }, { ...valid, lines: null },
    { ...valid, lines: ['-wrong', '+B'] },
    { ...valid, lines: [' wrong'] }, { ...valid, lines: ['?b'] },
    { ...valid, lines: [''] }, { ...valid, lines: [1] },
    { ...valid, lines: ['-b', '-c', '+B'] },
  ];
  for (const hunk of malformed) {
    assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  }
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, {
    oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' a'],
  }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, {
    oldStart: 3, oldLines: 1, newStart: 4, newLines: 1, lines: [' c'],
  }]), /hunk 1 does not apply/);
  assert.deepEqual(a, ['a', 'b', 'c']);
});

test('20,000-line small edits on unique and repetitive inputs', () => {
  for (const repetitive of [false, true]) {
    const a = Object.freeze(Array.from({ length: 20000 }, (_, i) => repetitive ? `line ${i % 3}` : `line ${i}`));
    const b = a.slice();
    b.splice(100, 1, 'replacement');
    b.splice(10000, 0, 'inserted');
    b.splice(19000, 1);
    Object.freeze(b);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const patched = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.deepEqual(patched, b);
    assert.ok(elapsed < 1000, `${elapsed.toFixed(2)} ms`);
    console.log(`${repetitive ? 'Repetitive' : 'Unique'} 20,000-line diff + hunks + application: ${elapsed.toFixed(2)} ms`);
  }
});

