'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Uint32Array(b.length + 1);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

function sequences(alphabet, maxLength) {
  const all = [Object.freeze([])];
  let level = all;
  for (let length = 1; length <= maxLength; length++) {
    const next = [];
    for (const prefix of level) {
      for (const line of alphabet) next.push(Object.freeze([...prefix, line]));
    }
    all.push(...next);
    level = next;
  }
  return all;
}

test('exhaustive minimality, deterministic ordering, and patch roundtrips', () => {
  const inputs = sequences(['', 'x', '+x'], 4);
  let pairs = 0;
  for (const a of inputs) {
    for (const b of inputs) {
      const script = diffLines(a, b);
